/* =======================================================
   10. 翻译内容 (独立外部气泡)
   ======================================================= */

:root {
  --translation-always-show: 1;
}

.msg-translation-wrapper {
  display: none !important;
}

.msg-translation-detached {
  display: block !important;
  margin-top: -3px !important;
  max-width: 100% !important;
  width: fit-content !important;
  min-width: 0 !important;      
  box-sizing: border-box !important;
}

.msg-translation-detached-content {
  background: #000000 !important;
  color: #ffffff !important;
  padding: 3px 6px 3px 6px !important;
  border-radius: 0px !important;
  box-shadow: none !important;  
  font-size: 15px !important;
  line-height: 1.5 !important;
  word-break: break-word !important;
  position: relative !important;
  min-width: 0 !important;      
  box-sizing: border-box !important;
}

.msg-translation-detached-them { 
  align-self: flex-start !important; 
  margin-left: 20px !important;
}
.msg-translation-detached-me { 
  align-self: flex-end !important; 
}

/* =======================================================
   🩹 补丁：彻底去除输入框打字时的蓝色发送小箭头
   ======================================================= */
.chat-detail-screen .send-btn-custom,
.chat-detail-screen [class*="send-btn"],
.chat-detail-screen .send-btn-custom svg {
  display: none !important;
}

/* =======================================================
   🌙 自动夜间模式适配 (Dark Mode)
   当手机切换夜间模式时自动生效
   ======================================================= */
@media (prefers-color-scheme: dark) {
  /* 1. 顶栏底栏背景变深色 */
  .chat-header-custom,
  .glass-header {
    background: #111111 !important;
    background-color: #111111 !important;
    border-bottom: 1px solid #222222 !important;
  }

  .input-area-custom {
    background-color: #111111 !important;
    border-top: 1px solid #222222 !important;
  }

  /* 2. 顶栏返回键变白 */
  .header-btn-back svg {
    color: #ffffff !important;
  }

  /* 3. 顶栏返回键旁的 99+ 换图 */
  .header-btn-back::after {
    background-image: url('https://imgbed.heliar.top/i/gMRCTZxd-hpb7nUc_IMG_1787.png') !important;
  }

  /* 4. 昵称白色，小字浅色 */
  .chat-header-title {
    color: #ffffff !important;
  }
  .header-profile-section::after {
    color: #aaaaaa !important;
  }

  /* 5. 顶栏设定键换图 */
  .header-btn-info::before {
    width: 20px !important;
    height: 20px !important;
    background-color: transparent !important;
    box-shadow: none !important;
    background-image: url('https://imgbed.heliar.top/i/8Mb_ly_OBGpoz7Ze_IMG_1783.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    transform: translateY(0) !important;
  }

  /* 6. 低栏输入框灰色，打字文字白色 */
  .input-row-wrapper {
    background: #2c2c2c !important;
    background-color: #2c2c2c !important;
  }
  .input-box-custom {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important; 
  }

  /* 7. 低栏图标排换图 */
  .input-area-custom::after {
    background-image: url('https://imgbed.heliar.top/i/JNiU3FCn3depJv_S_IMG_1782.png') !important;
  }

  /* 8. 双方气泡变成完全一致的深色 */
  div.chat-detail-screen .bubble-them-custom,
  div.chat-detail-screen .msg-plain-them,
  div.chat-detail-screen .bubble-me-custom,
  div.chat-detail-screen .msg-plain-me {
    background: #2a2a2a !important; /* 👈 我方和对方气泡统一为深灰色 */
    color: #ffffff !important;
  }

  /* 9. 夜间模式下语音时间和小图标调整 */
  div.chat-detail-screen .voice-duration {
    color: #aaaaaa !important;
    -webkit-text-fill-color: #aaaaaa !important;
  }

  /* 播放键在夜间稍微调暗，我方对方保持一致 */
  div.chat-detail-screen .bubble-them-custom .voice-play-btn,
  div.chat-detail-screen .msg-plain-them .voice-play-btn,
  div.chat-detail-screen .bubble-me-custom .voice-play-btn,
  div.chat-detail-screen .msg-plain-me .voice-play-btn {
    background: #444444 !important;
  }
  div.chat-detail-screen .bubble-them-custom .voice-play-btn svg,
  div.chat-detail-screen .bubble-them-custom .voice-play-btn path,
  div.chat-detail-screen .msg-plain-them .voice-play-btn svg,
  div.chat-detail-screen .msg-plain-them .voice-play-btn path,
  div.chat-detail-screen .bubble-me-custom .voice-play-btn svg,
  div.chat-detail-screen .bubble-me-custom .voice-play-btn path,
  div.chat-detail-screen .msg-plain-me .voice-play-btn svg,
  div.chat-detail-screen .msg-plain-me .voice-play-btn path {
    fill: #ffffff !important;
    stroke: #ffffff !important;
  }

  /* 10. 引用框夜间颜色 */
  div.chat-detail-screen .bubble-them-custom .msg-reply-block,
  div.chat-detail-screen .msg-plain-them .msg-reply-block,
  div.chat-detail-screen .bubble-me-custom .msg-reply-block,
  div.chat-detail-screen .msg-plain-me .msg-reply-block {
    background-color: rgba(255, 255, 255, 0.1) !important;
  }
  div.chat-detail-screen .bubble-them-custom .msg-reply-block-name,
  div.chat-detail-screen .msg-plain-them .msg-reply-block-name,
  div.chat-detail-screen .bubble-me-custom .msg-reply-block-name,
  div.chat-detail-screen .msg-plain-me .msg-reply-block-name {
    color: #aaaaaa !important;
  }
  div.chat-detail-screen .bubble-them-custom .msg-reply-block-text,
  div.chat-detail-screen .msg-plain-them .msg-reply-block-text,
  div.chat-detail-screen .bubble-me-custom .msg-reply-block-text,
  div.chat-detail-screen .msg-plain-me .msg-reply-block-text {
    color: #cccccc !important;
  }
  div.chat-detail-screen .bubble-them-custom .msg-reply-block::after,
  div.chat-detail-screen .msg-plain-them .msg-reply-block::after,
  div.chat-detail-screen .bubble-me-custom .msg-reply-block::after,
  div.chat-detail-screen .msg-plain-me .msg-reply-block::after {
    opacity: 0.4 !important;
  }

  /* 11. 思维链夜间模式适配 */
  div.chat-detail-screen {
    --thinking-panel-bg: #3a3a3c !important; /* 👈 浅灰色背景底色，增加对比度 */
    --thinking-text-color: #ffffff !important; /* 👈 字体改成亮白色，确保能看清 */
  }

  /* 确保夜间模式下，未展开时的 π_π 也是浅色可见的 */
  div.chat-detail-screen .nuo-thinking-btn::before {
    color: #aaaaaa !important;
  }
}

