/* ========== Galgame 戀愛風（底部對話框 · 粉色系）==========
   立繪居中、台詞收進底部對話框、控制鍵縮小讓路 */
:root {
    --vc-accent: #e5709a;
    --vc-answer-color: #f0a5c0;
    --vc-btn-bg: rgba(255, 240, 246, 0.28);
    --vc-btn-size: 48px;
    --vc-end-btn-size: 54px;
    --vc-text-size: 16px;
    --vc-name-size: 28px;
    --vc-bg-blur: 6px;
    --vc-bg-brightness: 0.75;
}

/* 台詞：底部對話框（經典 galgame 版式） */
.video-call-ai-text {
    bottom: 118px !important;
    padding: 0 14px !important;
    min-height: 0 !important;
}
.galgame-text-box { align-items: flex-start !important; }
.galgame-text-content {
    text-align: left !important;
    background: rgba(28, 16, 26, 0.72) !important;
    border: 1.5px solid rgba(240, 165, 192, 0.55) !important;
    border-radius: 14px !important;
    padding: 14px 16px !important;
    line-height: 1.75 !important;
    box-shadow: 0 6px 22px rgba(0, 0, 0, 0.35) !important;
}
.galgame-name-tag {
    background: linear-gradient(135deg, #e5709a, #f5b6cd) !important;
    color: #fff !important;
    padding: 3px 14px !important;
    border-radius: 999px 999px 0 0 !important;
    margin-left: 6px !important;
    text-shadow: none !important;
}
/* 旁白：無框斜體，與台詞區分 */
.vc-narration .galgame-text-content {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

/* 來電置中頭像大一點、粉色呼吸圈 */
.caller-avatar-container { --vc-avatar-size: 140px; }
.control-label { color: rgba(255, 226, 238, 0.85) !important; }

/* 說話中時，底部對話框輕微上浮（語義鉤子 .vc-speaking） */
.vc-speaking .video-call-ai-text { transition: bottom 0.25s ease !important; bottom: 126px !important; }

